import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.BU4O3IzQ.js";const m=JSON.parse('{"title":"AI 动态 · 2026-07-30","description":"","frontmatter":{"title":"AI 动态 · 2026-07-30","date":"2026-07-30T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-07/ai-news-2026-07-30.md","filePath":"news/2026-07/ai-news-2026-07-30.md","lastUpdated":1786092171000}'),o={name:"news/2026-07/ai-news-2026-07-30.md"};function n(i,e,l,c,d,h){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-07-30" tabindex="-1">AI 动态 · 2026-07-30 <a class="header-anchor" href="#ai-动态-·-2026-07-30" aria-label="Permalink to &quot;AI 动态 · 2026-07-30&quot;">​</a></h1><blockquote><p>截至 2026-07-30。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="词元无限一年连融三轮数亿元-打造企业软件工程ai-agent基础设施" tabindex="-1">词元无限一年连融三轮数亿元，打造企业软件工程AI Agent基础设施 <a class="header-anchor" href="#词元无限一年连融三轮数亿元-打造企业软件工程ai-agent基础设施" aria-label="Permalink to &quot;词元无限一年连融三轮数亿元，打造企业软件工程AI Agent基础设施&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-30">2026-07-30</time></p><p>由前字节跳动MarsCode和Trae负责人杨萍创立的词元无限，成立刚满一年即连续完成三轮融资，总金额数亿元。公司面向企业软件工程，提供AI Agent基础设施，旨在解决AI写代码效率高但企业整体交付提效不足的矛盾，将AI能力融入需求、评审、测试等全链路。对读者：关注企业级AI Coding基础设施的选型，其价值在于为结果而非工具付费。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/463013.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="无问芯穹发布跨集群异构推理架构pdd-延迟砍半成本降近40" tabindex="-1">无问芯穹发布跨集群异构推理架构PDD，延迟砍半成本降近40% <a class="header-anchor" href="#无问芯穹发布跨集群异构推理架构pdd-延迟砍半成本降近40" aria-label="Permalink to &quot;无问芯穹发布跨集群异构推理架构PDD，延迟砍半成本降近40%&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-30">2026-07-30</time></p><p>无问芯穹公布跨集群异构推理架构PDD的完整技术报告。该架构将传统PD分离链路创新解构为P-RLD-MD三级分离，利用广域网以太网串联多地同构数据中心，解决KV Cache传输延迟痛点。实测首Token延迟降低51.5%，单Token成本降低37.5%，盘活了分散的存量算力资源。对读者：该架构为降低大模型推理成本提供了新思路，尤其适合拥有多地数据中心的企业。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/463012.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="高通押注「个人ai」-发布产业白皮书定义终端新范式" tabindex="-1">高通押注「个人AI」，发布产业白皮书定义终端新范式 <a class="header-anchor" href="#高通押注「个人ai」-发布产业白皮书定义终端新范式" aria-label="Permalink to &quot;高通押注「个人AI」，发布产业白皮书定义终端新范式&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-30">2026-07-30</time></p><p>高通委托IDC发布产业白皮书，提出「个人AI」范式：以智能体为核心、以用户为中心，让手机、PC、眼镜等终端共享对用户的理解。白皮书指出，终端市场硬件参数竞争失效，AI渗透率逆势上扬，但需解决云端推理成本、延迟和隐私三大瓶颈，推动AI能力向端侧迁移。对读者：终端AI化趋势明确，开发者和厂商应关注端侧模型部署与个人智能体生态。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/463204.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="腾讯workbuddy重大升级-推出「人机双写」协同编辑" tabindex="-1">腾讯WorkBuddy重大升级，推出「人机双写」协同编辑 <a class="header-anchor" href="#腾讯workbuddy重大升级-推出「人机双写」协同编辑" aria-label="Permalink to &quot;腾讯WorkBuddy重大升级，推出「人机双写」协同编辑&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-30">2026-07-30</time></p><p>腾讯WorkBuddy发布V5.3.5版本，联合腾讯文档推出面向Agent时代的「人机双写」协同编辑能力。用户可在Word、Excel、PPT等文档中直接与AI共同创作、修改并实时协同，AI从「外挂」变为文档内的协作方，实现人人、人机、机机多端同步协作。对读者：企业用户可借此将AI深度融入现有办公流程，提升文档协作效率。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/462979.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="claude-code之父建议-每半年删除所有harness代码-让模型自由发挥" tabindex="-1">Claude Code之父建议：每半年删除所有Harness代码，让模型自由发挥 <a class="header-anchor" href="#claude-code之父建议-每半年删除所有harness代码-让模型自由发挥" aria-label="Permalink to &quot;Claude Code之父建议：每半年删除所有Harness代码，让模型自由发挥&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-30">2026-07-30</time></p><p>Claude Code之父Boris Cherny在YC访谈中提出激进的产品迭代策略：每六个月删除Claude.md、skills和hooks等所有Harness代码，通过消融实验测试模型真实能力。他认为模型是有机生物，产品设计应少预判、多测试，随着模型能力增强，应逐步解缚，让模型独立完成更难的任务。对读者：AI产品开发者应定期做减法，避免过度约束模型，释放其潜力。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/463433.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="chrome-devtools-推出官方-mcp-服务器-赋能编码-agent" tabindex="-1">Chrome DevTools 推出官方 MCP 服务器，赋能编码 Agent <a class="header-anchor" href="#chrome-devtools-推出官方-mcp-服务器-赋能编码-agent" aria-label="Permalink to &quot;Chrome DevTools 推出官方 MCP 服务器，赋能编码 Agent&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">ChromeDevTools/chrome-devtools-mcp</span><time datetime="2026-07-30">2026-07-30</time></p><p><img src="https://opengraph.githubassets.com/1/ChromeDevTools/chrome-devtools-mcp" alt="配图"></p><p>Chrome DevTools 团队发布官方 MCP 服务器项目 chrome-devtools-mcp，为编码 Agent 提供直接操作 Chrome DevTools 的能力。该项目开源在 GitHub 上，允许 AI 编程工具通过 MCP 协议与浏览器调试接口交互，实现页面分析、性能监控、DOM 操作等任务。对读者：前端开发者可借此将浏览器调试能力集成到 AI 工作流中，提升自动化测试与调试效率。</p><p class="news-entry-source"><a href="https://github.com/ChromeDevTools/chrome-devtools-mcp" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="gitlab-19-2-发布-用-ai-代理自动化处理安全待办事项" tabindex="-1">GitLab 19.2 发布，用 AI 代理自动化处理安全待办事项 <a class="header-anchor" href="#gitlab-19-2-发布-用-ai-代理自动化处理安全待办事项" aria-label="Permalink to &quot;GitLab 19.2 发布，用 AI 代理自动化处理安全待办事项&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-07-30">2026-07-30</time></p><p><img src="https://static001.infoq.cn/resource/image/cb/f5/cb04b18bf9e2f7b5f101259daf627ef5.jpg" alt="配图"></p><p>GitLab 发布 19.2 版本，新增多项 AI 代理功能以应对 AI 编码带来的安全审查积压问题。核心功能包括依赖项扫描自动修复（自动创建合并请求修复漏洞）、安全审查流程（检测逻辑缺陷）等，旨在将开发瓶颈从安全环节解放出来，同时保留人工审核环节。对读者：DevOps 团队可利用该版本自动化安全修复流程，减少手动打补丁的工作量。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/BSPHIPBaSTkEZT9eqgzL?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="实在agent登顶osworld双冠-桌面操作成功率突破90" tabindex="-1">实在Agent登顶OSWorld双冠，桌面操作成功率突破90% <a class="header-anchor" href="#实在agent登顶osworld双冠-桌面操作成功率突破90" aria-label="Permalink to &quot;实在Agent登顶OSWorld双冠，桌面操作成功率突破90%&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-07-30">2026-07-30</time></p><p><img src="https://static001.infoq.cn/resource/image/a7/b1/a7475c342ca606ce04213543e10fc2b1.jpg" alt="配图"></p><p>国内技术团队实在Agent在OSWorld权威榜单中以90.2%的总成功率、325.59分登顶总榜与Agentic Framework分榜双冠，成为首个突破90%成功率的桌面操作智能体。该评测基于真实Ubuntu系统，覆盖361项全场景任务，考核环境感知、长链路规划等硬核能力。对读者：该成果展示了桌面Agent的技术新高度，可关注其在自动化办公与测试中的应用潜力。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/4hUcQzeCeKm0wqkc4Zdc?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>（本日无新条目）</p></div>',8)])])}const u=a(o,[["render",n]]);export{m as __pageData,u as default};
